import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate } from './dates.js';


/**
 * Calculate the total amount for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} qty × unitPrice in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * VAT is calculated per line on the amount after discount, then rounded per line.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }} all in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let totalDiscount = 0;
  let totalVat = 0;

  for (const line of invoice.lines) {
    const lineTotal = line.qty * line.unitPrice;
    const lineDiscount = roundCents(lineTotal * ((line.discountPercent || 0) / 100));
    const lineAmountAfterDiscount = lineTotal - lineDiscount;
    const lineVat = roundCents(lineAmountAfterDiscount * (line.vatRate / 100));

    subtotal += lineTotal;
    totalDiscount += lineDiscount;
    totalVat += lineVat;
  }

  const discount = Math.max(0, totalDiscount);
  const vat = Math.max(0, totalVat);
  const total = Math.max(0, subtotal - discount + vat);

  return { subtotal, discount, vat, total };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ status: string, customerId: string, lines: Array }} invoice
 * @param {{ sku: string, qty: unknown, discountPercent?: unknown }} input
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

  const product = getProduct(sku);
  if (!product.ok) {
    return product;
  }

  const customer = getCustomer(invoice.customerId);
  const tierDiscount = customer.ok ? TIER_DISCOUNTS[customer.value.tier] || 0 : 0;

  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    newLines = invoice.lines.map((line, index) => {
      if (index === existingLineIndex) {
        return {
          ...line,
          qty: line.qty + qty,
          discountPercent: discountPercent !== undefined ? discountPercent : line.discountPercent,
        };
      }
      return { ...line };
    });
  } else {
    newLines = [
      ...invoice.lines.map((line) => ({ ...line })),
      {
        sku,
        name: product.value.name,
        qty,
        unitPrice: product.value.unitPrice,
        vatRate: product.value.vatRate,
        discountPercent: discountPercent !== undefined ? discountPercent : tierDiscount,
      },
    ];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku).map((line) => ({ ...line }));

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: { status: string, number: string, lines: Array } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Create a draft invoice with the given customer and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: unknown }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  const normalizedCustomerId = normalizeId(customerId);
  const customer = getCustomer(normalizedCustomerId);
  if (!customer.ok) {
    return customer;
  }

  if (!lines || lines.length === 0) {
    return fail('NO_LINES');
  }

  const tierDiscount = TIER_DISCOUNTS[customer.value.tier] || 0;

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    if (line.discountPercent !== undefined) {
      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    }

    const product = getProduct(line.sku);
    if (!product.ok) {
      return product;
    }

    invoiceLines.push({
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
      discountPercent: line.discountPercent !== undefined ? line.discountPercent : tierDiscount,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

