  const totals = invoiceTotals(result.value);
  // Line 1: 10 × €95.00 = €950.00, 10% discount = €95.00, amount = €855.00, 21% VAT = €179.55
  // Line 2: 100 × €0.50 = €50.00, 25% discount = €12.50, amount = €37.50, 21% VAT = €7.88
  // Subtotal: €1,000.00, Discount: €107.50, VAT: €187.43, Total: €1,079.93
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10750);
