  assert.equal(result2025.ok, true);
  assert.equal(result2026.ok, true);

  const existing = ['INV-2025-0001', 'INV-2026-0001'];

  const issue2025 = issueInvoice(result2025.value, existing);
  const issue2026 = issueInvoice(result2026.value, existing);

  assert.equal(issue2025.value.number, 'INV-2025-0002');
  assert.equal(issue2026.value.number, 'INV-2026-0002');
});

