});

test('issueInvoice preserves invoice properties', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  assert.equal(result.ok, true);
  const issueResult = issueInvoice(result.value, []);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.customerId, 'C-003');
  assert.equal(issueResult.value.issueDate, '2026-10-07');
  assert.equal(issueResult.value.lines.length, 2);
  assert.equal(issueResult.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(issueResult.value.lines[0].name, 'Logo package');
  assert.equal(issueResult.value.lines[1].sku, 'STICKER');
});

